        res = -int(str(-x)[::-1])
    else:
        res = int(str(x)[::-1])

    if res > 2**31 - 1 or res < -2**31:
        return 0
    else:
        return res

def divide(dividend: int, divisor: int) -> int:
    if dividend == 0:
        return 0
    elif dividend == -2**31 and divisor == -1:
        return 2**31 - 1
    else:
        if (dividend < 0 and divisor > 0) or (dividend > 0 and divisor < 0):
            sign = -1
        else:
            sign = 1

        quotient = 0
        multiple = 1
        dividend = abs(dividend)
        divisor = abs(divisor)

        while dividend >= (divisor << 1):
            divisor <<= 1
            multiple <<= 1

        while multiple > 0:
            if dividend >= divisor:
                dividend -= divisor
                quotient += multiple

            divisor >>= 1
            multiple >>= 1

        return sign * quotient

def myPow(x: float, n: int) -> float:
    def calc_power(x, n):
        if x == 0:
            return 0
        if n == 0:
            return 1

        if n < 0:
            ans = calc_power(x, -n)
            return 1 / ans

        ans = calc_power(x, n // 2)
        ans = ans * ans

        if n % 2 == 1:
            return ans * x
        else:
            return ans

    return calc_power(x, n)

