def preimageSizeFZF(k: int) -> int:
    m = math.floor(math.log(4 * k + 1, 5))

    if m > 0:
        unit = (5**m - 1) // 4
        if k // unit > 4:
            return 0
        else:
            k = k % unit
            m -= 1
            while m > 0:
                unit = (5**m - 1) // 4
                if k // unit > 4:
                    return 0
                else:
                    k = k % unit
                    m -= 1
    return 5

