def canTraverseAllPairs(nums: List[int]) -> bool:
    if len(nums) == 1:
        return True  # Only one element.

    nums = list(set(nums))  # Convert to a set to remove duplicates.

    if 1 in nums:
        return False  # Contains 1.

    # Build a graph based on GCD connections
    graph = defaultdict(list)

    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if gcd(nums[i], nums[j]) > 1:
                graph[i].append(j)
                graph[j].append(i)

    # Perform BFS or DFS to check connectivity
    visited = [False] * len(nums)

    def bfs(start):
        queue = deque([start])
        visited[start] = True
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

    # Start BFS from the first index
    bfs(0)

    # Check if all nodes are visited
    return all(visited)

