def waysToReachStair(target: int) -> int:
    current_sum = 1
    ways = 0

    if target == 0:
        ways += 2  # Two ways to reach stair 0
    elif target == 1:
        ways += 4  # Four ways to reach stair 1
    else:
        pas = [[0] * (target + 2) for _ in range(target + 2)]
        pas[0][0] = 1

        for row in range(1, target + 2):
            pas[row][0] = 1
            for col in range(1, row + 1):
                pas[row][col] = pas[row - 1][col] + pas[row - 1][col - 1]

        for i in range(30):  # 30 is a safe upper limit for jumps
            current_sum += 1 << i
            if current_sum >= target and current_sum - target <= i + 2:
                n = i + 2
                r = current_sum - target
                if r <= n:
                    ways += pas[n][r]

    return ways

