def kthCharacter(k: int, operations: List[int]) -> str:
    i = ceil(log2(k)) - 1
    count = 0

    while k > 1:
        if k > (1 << i):
            if operations[i] == 1:
                count += 1
            k -= (1 << i)
        i -= 1

    return chr(97 + (count % 26))
